export const VOICE_FPS = 30;
export const VOICE = {"en":{"learn":{"duration":15.76,"cues":[{"who":"NURI","text":"Let's solve it together. What should we do with the +3?","start":0.6,"end":3.5},{"who":"Student","text":"Move it to the other side?","start":3.95,"end":5.44},{"who":"NURI","text":"Exactly. 11 − 3 gives us 2x = 8.","start":5.79,"end":9.63},{"who":"NURI","text":"Now divide both sides by 2. So x = 4. Well done!","start":10.13,"end":14.16}],"env":""},"reception":{"duration":11.82,"cues":[{"who":"NURI","text":"Hi, welcome in! Would you like to take a number?","start":0.6,"end":3.23},{"who":"Customer","text":"Yes, please.","start":3.63,"end":4.57},{"who":"NURI","text":"You're A012. It's about five minutes.","start":4.92,"end":7.66},{"who":"NURI","text":"I've let the staff know you're here. Have a seat!","start":8.11,"end":10.22}],"env":""},"assist":{"duration":16.01,"cues":[{"who":"You","text":"NURI, what matters most today?","start":0.6,"end":2.38},{"who":"NURI","text":"Three things. Your 9:30 client call comes first.","start":2.78,"end":5.82},{"who":"NURI","text":"Then quotation #24. The draft is ready on your laptop.","start":6.12,"end":9.89},{"who":"You","text":"Great, show me.","start":10.29,"end":11.27},{"who":"NURI","text":"It's open. I won't send anything until you say so.","start":11.62,"end":14.41}],"env":""},"companion":{"duration":13.35,"cues":[{"who":"NURI","text":"Good evening, Mak Su. Have you taken your 9 pm medicine?","start":0.6,"end":4.32},{"who":"Mak Su","text":"Yes, just now.","start":4.77,"end":6.04},{"who":"NURI","text":"Great. Shall I call Aisyah to say goodnight?","start":6.39,"end":8.65},{"who":"Mak Su","text":"Yes, please.","start":9.05,"end":10.16},{"who":"NURI","text":"Calling Aisyah now…","start":10.51,"end":11.75}],"env":""}},"ms":{"learn":{"duration":16.93,"cues":[{"who":"NURI","text":"Jom kita selesaikan sama-sama. Apa kita nak buat dengan +3 ni?","start":0.6,"end":4.8},{"who":"Pelajar","text":"Pindahkan ke sebelah sana?","start":5.25,"end":6.91},{"who":"NURI","text":"Betul. 11 − 3, jadi 2x = 8.","start":7.26,"end":10.51},{"who":"NURI","text":"Sekarang bahagi kedua-dua belah dengan 2. Jadi x = 4. Bagus!","start":11.01,"end":15.33}],"env":""},"reception":{"duration":12.49,"cues":[{"who":"NURI","text":"Hai, selamat datang! Nak ambil nombor giliran?","start":0.6,"end":3.21},{"who":"Pelanggan","text":"Ya, boleh.","start":3.61,"end":4.45},{"who":"NURI","text":"Nombor anda A012. Lebih kurang lima minit.","start":4.8,"end":7.82},{"who":"NURI","text":"Saya dah maklumkan staf. Silakan duduk dulu!","start":8.27,"end":10.89}],"env":""},"assist":{"duration":18.65,"cues":[{"who":"Anda","text":"NURI, apa yang paling penting hari ni?","start":0.6,"end":2.82},{"who":"NURI","text":"Tiga perkara. Panggilan klien pukul 9:30 paling utama.","start":3.22,"end":6.98},{"who":"NURI","text":"Lepas tu sebut harga #24. Draf dah siap dalam laptop anda.","start":7.28,"end":11.37},{"who":"Anda","text":"Okey, tunjuk saya.","start":11.77,"end":13.17},{"who":"NURI","text":"Dah dibuka. Saya takkan hantar apa-apa sampai anda setuju.","start":13.52,"end":17.05}],"env":""},"companion":{"duration":14.8,"cues":[{"who":"NURI","text":"Selamat malam, Mak Su. Mak Su dah makan ubat pukul 9 malam?","start":0.6,"end":4.17},{"who":"Mak Su","text":"Dah, baru tadi.","start":4.62,"end":5.85},{"who":"NURI","text":"Bagus. Nak saya telefon Aisyah, ucap selamat malam?","start":6.2,"end":9.17},{"who":"Mak Su","text":"Boleh juga.","start":9.57,"end":10.68},{"who":"NURI","text":"Okey, saya telefon Aisyah sekarang…","start":11.03,"end":13.2}],"env":""}}};
